sections.fragmentShader:
precision highp float;
varying vec2 v_texCoord;
uniform float u_time;
uniform float u_blurAmount;
uniform float u_anamorphic;
uniform vec2 u_resolution;

void main() {
    vec2 uv = v_texCoord;

    // Create animated bright spots
    float pattern = 0.0;
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        vec2 spot = vec2(
            0.5 + 0.3 * sin(u_time * 0.5 + fi * 1.3),
            0.5 + 0.3 * cos(u_time * 0.7 + fi * 1.7)
        );
        float d = length(uv - spot);
        pattern += smoothstep(0.08, 0.0, d) * (0.8 + 0.2 * sin(fi));
    }

    // Apply anamorphic blur with offset samples
    vec3 color = vec3(0.0);
    float total = 0.0;

    for (int i = -7; i <= 7; i++) {
        float fi = float(i);
        float weight = exp(-fi * fi / 20.0);

        // Anamorphic: stretch horizontal, compress vertical
        vec2 offset = vec2(
            fi * u_blurAmount * 0.015 * (1.0 + u_anamorphic * 2.5),
            fi * u_blurAmount * 0.015 * (1.0 - u_anamorphic * 0.9)
        );

        vec2 sampleUV = uv + offset;

        // Sample pattern at offset
        float samplePattern = 0.0;
        for (int j = 0; j < 5; j++) {
            float fj = float(j);
            vec2 spot = vec2(
                0.5 + 0.3 * sin(u_time * 0.5 + fj * 1.3),
                0.5 + 0.3 * cos(u_time * 0.7 + fj * 1.7)
            );
            float d = length(sampleUV - spot);
            samplePattern += smoothstep(0.08, 0.0, d) * (0.8 + 0.2 * sin(fj));
        }

        color += vec3(samplePattern) * weight;
        total += weight;
    }
    color /= total;

    // Color grading - teal/gold cinematic look
    vec3 teal = vec3(0.18, 0.83, 0.75);
    vec3 gold = vec3(0.91, 0.73, 0.14);
    color = mix(teal * 0.3, gold, color.r) + color * 0.5;

    // Subtle vignette
    float vignette = 1.0 - length(uv - 0.5) * 0.8;
    color *= vignette;

    // Dark background
    vec3 bg = vec3(0.04, 0.06, 0.08);
    color = max(color, bg);

    gl_FragColor = vec4(color, 1.0);
}

